/* custard_glue.h — hand-written glue between Custard.{c,h} and its C callers.
 *
 * Custard.{c,h} are generated by `make -C generational snapshot` (F*'s Custard
 * backend, --custard_backend C).  This header and custard_glue.c are NOT
 * generated: they are the only unverified code between the extraction and the
 * bridge, and replace KaRaMeL's krmlinit.{c,h}.
 */

#ifndef CUSTARD_GLUE_H
#define CUSTARD_GLUE_H

#include "Custard.h"

/* The pair types in the API are monomorphizer specializations whose names
 * Custard does not promise to keep stable (its warning 377), so callers spell
 * them only through these aliases.  Fields are _1 / _2. */
typedef FStar_Pervasives_Native_tuple2__uint64_uint64 K___uint64_t_uint64_t; /* allocate: (fp, obj) */
typedef FStar_Pervasives_Native_tuple2__uint64_bool   K___uint64_t_bool;     /* gen_gc: (fp, ok)    */

/* Initialise the extracted globals.  Call after zero_addr, heap_size_u64 and
 * minor_heap_size_u64 have been configured, as krmlinit_globals was. */
void gc_init_globals(void);

#endif /* CUSTARD_GLUE_H */
